export function useAvailableGauges(enabled = true) {
  return useQuery({
    queryKey: ["available-gauges-with-pools"],
    queryFn: async () => {
      const gaugeData = await fetchDataFromSubgraph(
        GET_AVAILABLE_GAUGES_QUERY,
        GAUGES_SUBGRAPH_URL
      );
      if (!gaugeData?.gauges || gaugeData.gauges.length === 0) {
        return [];
      }
      const allPoolIds = gaugeData.gauges.map((g) => g.pool.toLowerCase());
      const v2Data = await fetchDataFromSubgraph(
        GET_V2_POOLS_BY_IDS,
        V2_SUBGRAPH_URL,
        { ids: allPoolIds }
      );
      const v2Pools = v2Data?.pairs || [];
      const v3Data = await fetchDataFromSubgraph(
        GET_V3_POOLS_BY_IDS,
        V3_SUBGRAPH_URL,
        { ids: allPoolIds }
      );
      const v3Pools = v3Data?.pools || [];
      const poolMap = /* @__PURE__ */ new Map();
      v2Pools.forEach((pool) => poolMap.set(pool.id.toLowerCase(), pool));
      v3Pools.forEach((pool) => poolMap.set(pool.id.toLowerCase(), {
        ...pool,
        reserveUSD: pool.totalValueLockedUSD
      }));
      const enhancedGauges = gaugeData.gauges.map((gauge) => {
        const poolData = poolMap.get(gauge.pool.toLowerCase());
        if (poolData) {
          return {
            ...gauge,
            token0: poolData.token0,
            token1: poolData.token1,
            tickSpacing: poolData.tickSpacing,
            // Include tick spacing for V3 pools
            reserveUSD: poolData.reserveUSD,
            volumeUSD: poolData.volumeUSD,
            votes: gauge.totalWeight
          };
        }
        return gauge;
      });
      return enhancedGauges;
    },
    enabled,
    staleTime: 3e4,
    refetchInterval: 6e4
  });
}
export function calculatePoolIncentives(gaugePool) {
  let totalIncentives = 0;
  let totalEmissions = 0;
  if (gaugePool.emissions && gaugePool.emissions !== "0") {
    try {
      totalEmissions = parseFloat((BigInt(gaugePool.emissions) / BigInt(10 ** 18)).toString());
    } catch (error) {
      console.warn("Failed to parse emissions:", gaugePool.emissions, error);
    }
  }
  if (gaugePool.rewardDistributions) {
    gaugePool.rewardDistributions.forEach((distribution) => {
      if (distribution.amount && distribution.amount !== "0") {
        try {
          const amount = parseFloat((BigInt(distribution.amount) / BigInt(10 ** 18)).toString());
          totalIncentives += amount;
        } catch (error) {
          console.warn("Failed to parse reward distribution:", distribution.amount, error);
        }
      }
    });
  }
  const totalRewards = totalIncentives + totalEmissions;
  const incentivesFormatted = totalRewards > 0 ? `${totalRewards.toLocaleString(void 0, { maximumFractionDigits: 0 })} ABX` : "No available incentives";
  return {
    totalIncentives,
    totalEmissions,
    totalRewards,
    incentivesFormatted
  };
}
export function calculatePoolVAPR(gaugePool, tvlUSD) {
  const { totalRewards } = calculatePoolIncentives(gaugePool);
  if (totalRewards === 0) return "0.00";
  if (!tvlUSD || tvlUSD === 0) return "0.00";
  const abxPrice = 1;
  const weeklyRewards = totalRewards;
  const annualRewards = weeklyRewards * 52 * abxPrice;
  const apr = annualRewards / tvlUSD * 100;
  return apr.toFixed(2);
}
