"use strict";
import { AnimatePresence, motion } from "framer-motion";
import styled from "styled-components";
import { Flex, Separator, Text, styled as UiStyled } from "ui/src";
import { Check, Plus } from "ui/src/components/icons";
import { useFilters } from "../contexts/FilterContext";
const Button = styled.button`
  padding: 10px 10px;
  background-color: transparent;
  border: none;
  cursor: pointer;
  hover {
    color: red;
  }
`;
const TextCotainer = UiStyled(Text, {
  variant: "body3",
  color: "$neutral1",
  cursor: "pointer",
  hoverStyle: {
    color: "$accent1"
  }
});
const Checkmark = function() {
  return <Check color={"$greenVibrant"} size={"$icon.12"} />;
};
const PlusSign = function() {
  return <Plus color={"$neutral1"} size={"$icon.12"} />;
};
const FIlterContainer = UiStyled(Flex, {
  row: true,
  flexWrap: "nowrap",
  alignItems: "center",
  borderStyle: "solid",
  borderWidth: 1,
  borderColor: "$surface3",
  borderRadius: "$rounded12"
});
export default function FilterPoolsButtons() {
  const { filters, setFilters } = useFilters();
  const GenerateFilterButton = function({
    type,
    divider
  }) {
    const handleFilter = function(value) {
      switch (type) {
        case "Basic":
          setFilters({
            ...filters,
            Basic: value,
            Concentrated: value ? false : filters.Concentrated
          });
          break;
        case "Concentrated":
          setFilters({
            ...filters,
            Concentrated: value,
            Basic: value ? false : filters.Basic
          });
          break;
        case "Stable":
          setFilters({
            ...filters,
            Stable: value,
            Volatile: value ? false : filters.Volatile
          });
          break;
        case "Volatile":
          setFilters({
            ...filters,
            Volatile: value,
            Stable: value ? false : filters.Stable
          });
          break;
        case "Incentivized":
          setFilters({
            ...filters,
            Incentivized: value
          });
          break;
      }
    };
    return <>
        {divider && <Separator vertical height={"100%"} />}
        <Button onClick={() => handleFilter(!filters[type])}>
          <TextCotainer>{type}</TextCotainer> {filters[type] ? <Checkmark /> : <PlusSign />}
        </Button>
      </>;
  };
  return <Flex
    maxWidth={750}
    width={"100%"}
    $platform-web={{
      overflow: "auto"
    }}
  >
      <Flex row gap={"$spacing12"} pb={0} $lg={{ pb: "$spacing16" }} width={"100%"}>
        <FIlterContainer>
          <GenerateFilterButton type={"Basic"} />
          <GenerateFilterButton type={"Concentrated"} divider />
        </FIlterContainer>

        <AnimatePresence>
          {filters.Basic && <motion.div
    initial={{ width: 0, opacity: 0 }}
    animate={{ width: "200px", opacity: 1 }}
    exit={{ width: 0, opacity: 0 }}
    transition={{
      width: { duration: 0.3, ease: "easeInOut" },
      opacity: { duration: 0.2, ease: "easeOut" }
    }}
  >
              <FIlterContainer>
                <GenerateFilterButton type={"Stable"} />
                <GenerateFilterButton type={"Volatile"} divider />
              </FIlterContainer>
            </motion.div>}
        </AnimatePresence>

        <FIlterContainer>
          <GenerateFilterButton type={"Incentivized"} />
        </FIlterContainer>

        {
    /* <FIlterContainer>
      <GenerateFilterButton type={'ALM'} />
    </FIlterContainer> */
  }
      </Flex>
    </Flex>;
}
